const tarjetaId = Number(pm.collectionVariables.get("tarjetaId"));

// Armamos la consulta SQL usando el ayudante de la colección
const request = utils.bodySqlRest(
    "SELECT id, estado FROM tarjetas WHERE id = $1",
    [tarjetaId]
);

// Enviamos la consulta ANTES de que se ejecute el bloqueo
pm.sendRequest(request, (err, res) => {
    if (err) {
        console.error("Fallo la consulta previa:", err);
        return;
    }
    
    const rows = res.json().data || [];
    const tarjeta = rows.find(r => r.id === tarjetaId);
    console.log("Estado ANTES de bloquear:", tarjeta ? tarjeta.estado : "No existe");
});

